  'help.faq.cantLogin.a': 'Таны имэйл болон нууц үг зөв байгаа эсэхийг шалгаарай. Нууц үгээ мартсан бол, нэвтрэх дэлгэц дээр "Нууц үгээ мартсан уу?" дээр дарна уу. Асуудал үргэлжилбэл, тусламжийн тикет үүсгээрэй.',
